// Generated by tour2playwright from a Tour Recorder export, then hand-edited.
// Source tour: Inventory User Guide - Stock Valuation by Product & Category
// Hand edits: text/label-based selectors instead of positions, state assertions, result screenshots, wide viewport,
// login fallback. READ-ONLY: it only looks at reports, products and categories; nothing is created or changed.
import { test, expect } from "../../../../core/fixtures/index";
import type { Page, Locator } from "@playwright/test";
import fs from "node:fs";

const SHOT_DIR = "tools/tour2playwright/generated/screenshots/inventory-user-guide-stock-valuation-by-product-category";

// A step's own screenshot is taken BEFORE its action; this keeps one of the finished screen.
async function resultShot(page: Page, n: number) {
  fs.mkdirSync(SHOT_DIR, { recursive: true });
  await page.screenshot({ path: `${SHOT_DIR}/step-${String(n).padStart(2, "0")}-result.png` });
}

// Screenshot the current page with the target element outlined.
async function shot(page: Page, loc: Locator, file: string) {
  try {
    await loc.scrollIntoViewIfNeeded({ timeout: 5000 });
    await loc.evaluate((el) => el.setAttribute("data-t2p", "1"));
    await page.addStyleTag({
      content: '[data-t2p="1"]{outline:3px solid #e01e5a !important;outline-offset:2px !important;}',
    });
  } catch {}
  fs.mkdirSync(SHOT_DIR, { recursive: true });
  await page.screenshot({ path: `${SHOT_DIR}/${file}` });
  try { await loc.evaluate((el) => el.removeAttribute("data-t2p")); } catch {}
}

test.describe("Inventory User Guide - Stock Valuation by Product & Category @module:inventory @step:business @e2e", () => {
  // At the default 1280px some top-menu entries collapse into the "+" overflow.
  test.use({ viewport: { width: 1600, height: 900 } });

  test("Inventory User Guide - Stock Valuation by Product & Category", async ({ page, rpc }) => {
    test.setTimeout(240_000);
    // The tour was recorded in company "Jinasena (Pvt) Ltd." (id 1), where categories use Automated valuation (their
    // form shows the stock valuation accounts). The saved session opens on another company, so select company 1.
    await page.context().addCookies([{ name: "cids", value: "1", url: process.env.ODOO_BASE_URL ?? "http://localhost:8069" }]);
    await page.goto("/web");

    // The saved browser session can expire — fall back to the login form if we got bounced to it.
    const emailBox = page.getByRole("textbox", { name: "Email" });
    if (await emailBox.isVisible({ timeout: 8_000 }).catch(() => false)) {
      await emailBox.fill(process.env.ADMIN_EMAIL ?? "admin");
      await page.getByRole("textbox", { name: "Password" }).fill(process.env.ADMIN_PASSWORD ?? "admin");
      await page.getByRole("button", { name: "Log in" }).click();
      await page.waitForSelector(".o_main_navbar, .o_home_menu", { state: "visible", timeout: 45_000 });
    }
    await page.waitForLoadState("networkidle", { timeout: 10_000 }).catch(() => {});
    // The tour starts INSIDE the Inventory app, but /web lands on the app picker.
    const app = page.getByRole("option", { name: "Inventory", exact: true });
    if (await app.isVisible({ timeout: 10_000 }).catch(() => false)) await app.click();
    await expect(page.locator(".o_menu_sections")).toBeVisible({ timeout: 45000 });

    const run = async (n: number, title: string, loc: Locator, act?: (l: Locator) => Promise<void>, result = false) => {
      await test.step(`${String(n).padStart(2, "0")}. ${title}`, async () => {
        const l = loc.first();
        await l.waitFor({ state: "visible", timeout: 45000 });
        await shot(page, l, `step-${String(n).padStart(2, "0")}.png`);
        if (act) await act(l);
        if (result) await resultShot(page, n);
      });
    };
    const topMenu = (name: string) => page.locator(".o_menu_sections .dropdown-toggle, .o_menu_sections > a").filter({ hasText: new RegExp(`^${name}$`) });
    const menu = (xmlid: string) => page.locator(`[data-menu-xmlid="${xmlid}"]`);
    const toggler = page.locator("button.o_searchview_dropdown_toggler");
    const groupItem = (name: string) => page.locator(".o_group_by_menu .o_menu_item").filter({ hasText: new RegExp(`^${name}$`) });
    const facets = page.locator(".o_searchview_facet");

    // ------------------------------------------------------------------ Part 1: the Valuation report
    // On this database the "Valuation" menu entry has been deleted (its xml id points to a menu that no longer
    // exists), so the recorded click cannot be repeated. The report itself still exists: when the menu entry is
    // missing, open the same report through its action.
    let valuationViaMenu = true;
    await run(1, "Open the Reporting menu", topMenu("Reporting"), async (l) => {
      await l.click();
      await expect(page.locator(".dropdown-menu .dropdown-item").first()).toBeVisible({ timeout: 15000 });
      valuationViaMenu = await menu("stock_account.menu_valuation").first().isVisible().catch(() => false);
    }, true);
    await test.step("02. Open Valuation", async () => {
      if (valuationViaMenu) {
        const l = menu("stock_account.menu_valuation").first();
        await shot(page, l, "step-02.png");
        await l.click();
      } else {
        await shot(page, page.locator(".dropdown-menu").first(), "step-02.png");
        await page.keyboard.press("Escape");
        await page.goto("/web#action=stock_account.stock_valuation_layer_action");
      }
      await expect(page.locator(".o_list_view, .o_pivot, .o_graph_renderer").first(), "Stock Valuation report opened").toBeVisible({ timeout: 45000 });
      await expect(page.locator(".o_breadcrumb, .o_control_panel").first()).toContainText(/Valuation/i);
      await resultShot(page, 2);
    });
    await run(3, "Toggle the search panel", toggler, async (l) => {
      await l.click();
      await expect(groupItem("Product Category"), "group-by options open").toBeVisible({ timeout: 15000 });
    }, true);
    await run(4, "Switch off the default grouping by Product", groupItem("Product"), async (l) => {
      await l.click();
    }, true);
    await run(5, "Group by Product Category", groupItem("Product Category"), async (l) => {
      await l.click();
      await expect(facets.filter({ hasText: /Product Category/ }), "grouped by category").toBeVisible({ timeout: 20000 });
    }, true);
    await run(6, "Add Product as a second level", groupItem("Product"), async (l) => {
      await l.click();
      await expect(facets.filter({ hasText: /Product Category/ }).filter({ hasText: /Product$|> Product/ }).first(), "category, then product").toBeVisible({ timeout: 20000 });
    }, true);
    await run(7, "Expand a category", page.locator("tr.o_group_header th.o_group_name, .o_group_header .o_group_name").first(), async (l) => {
      const rowsBefore = await page.locator("tbody tr").count();
      await l.click();
      await expect.poll(() => page.locator("tbody tr").count(), { message: "expanding should list the products inside" }).toBeGreaterThan(rowsBefore);
    }, true);
    await run(8, "Read the Total Value column", page.locator("thead th").filter({ hasText: /Total Value/ }), async (l) => {
      await expect(l).toBeVisible();
    });

    // ------------------------------------------------------------------ Part 2: a product and a category
    await run(9, "Open the Products menu", topMenu("Products"), async (l) => {
      await l.click();
      await expect(page.locator(".dropdown-menu .dropdown-item").filter({ hasText: /^Products$/ }).first()).toBeVisible({ timeout: 15000 });
    }, true);
    await run(10, "Open Products", page.locator(".dropdown-menu .dropdown-item").filter({ hasText: /^Products$/ }), async (l) => {
      await l.click();
      await expect(page.locator(".o_kanban_view, .o_list_view").first(), "product list opened").toBeVisible({ timeout: 30000 });
    }, true);
    await run(11, "Open a product", page.locator(".o_kanban_record, .o_data_row").first(), async (l) => {
      await l.click();
      await expect(page.locator(".o_form_view"), "product form opened").toBeVisible({ timeout: 30000 });
    }, true);
    await run(12, "Read the product's Cost", page.locator("#standard_price_0, .o_field_widget[name='standard_price']").first(), async (l) => {
      await expect(l).toBeVisible();
    });
    await run(13, "Open the Configuration menu", topMenu("Configuration"), async (l) => {
      await l.click();
      await expect(menu("stock.menu_product_category_config_stock").first()).toBeVisible({ timeout: 15000 });
    }, true);
    await run(14, "Open Product Categories", menu("stock.menu_product_category_config_stock"), async (l) => {
      await l.click();
      await expect(page.locator(".o_list_view"), "categories list opened").toBeVisible({ timeout: 30000 });
    }, true);
    await run(15, "Open a product category", page.locator("input.o_searchview_input"), async (l) => {
      // The list holds 183 categories over several pages and two companies use the same names. Search for the
      // tour's category and open the matching rows in turn until the form shows Automated valuation.
      await l.fill("FG-4W-23");
      await l.press("Enter");
      const rows = page.locator(".o_data_row").filter({ hasText: /FG-4W-23/ });
      await expect(rows.first(), "category found").toBeVisible({ timeout: 20000 });
      const count = await rows.count();
      let opened = false;
      for (let i = 0; i < count; i++) {
        await rows.nth(i).click();
        await expect(page.locator(".o_form_view"), "category form opened").toBeVisible({ timeout: 30000 });
        if (await page.locator(".o_field_widget[name='property_stock_valuation_account_id']").first().isVisible({ timeout: 3000 }).catch(() => false)) { opened = true; break; }
        await page.locator(".o_back_button, .breadcrumb-item").filter({ hasText: /Product Categories/ }).first().click();
        await expect(rows.first()).toBeVisible({ timeout: 30000 });
      }
      expect(opened, "a FG-4W-23 category with Automated valuation was opened").toBe(true);
    }, true);
    await run(16, "Costing Method", page.locator("#property_cost_method_0, .o_field_widget[name='property_cost_method']").first(), async (l) => {
      await expect(l).toBeVisible();
    });
    await run(17, "Inventory Valuation", page.locator("#property_valuation_1, #property_valuation_0, .o_field_widget[name='property_valuation']").first(), async (l) => {
      await expect(l).toBeVisible();
    });
    await run(18, "Stock Valuation Account", page.locator("#property_stock_valuation_account_id_0, .o_field_widget[name='property_stock_valuation_account_id']").first(), async (l) => {
      await expect(l).toBeVisible();
    });

    // ------------------------------------------------------------------ Part 3: the on-hand Stock report
    await run(19, "Open the Reporting menu again", topMenu("Reporting"), async (l) => {
      await l.click();
      await expect(menu("stock.menu_product_stock").first()).toBeVisible({ timeout: 15000 });
    }, true);
    await run(20, "Open Stock", menu("stock.menu_product_stock"), async (l) => {
      await l.click();
      await expect(page.locator(".o_list_view, .o_pivot, .o_kanban_view").first(), "Stock report opened").toBeVisible({ timeout: 30000 });
    }, true);
    await run(21, "Toggle the search panel", toggler, async (l) => {
      await l.click();
      await expect(groupItem("Product Category")).toBeVisible({ timeout: 15000 });
    }, true);
    await run(22, "Group by Product Category", groupItem("Product Category"), async (l) => {
      await l.click();
      await expect(facets.filter({ hasText: /Product Category/ }), "grouped by category").toBeVisible({ timeout: 20000 });
    }, true);
  });
});
